package stirling.software.SPDF.controller.api.pipeline;

import static org.junit.jupiter.api.Assertions.*;

import java.io.File;
import java.io.FileOutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

public class PipelineProcessorTest {

    @Test
    void shouldNotUnzipCbzFile(@TempDir Path tempDir) throws Exception {
        // Create a CBZ file
        Path cbzPath = tempDir.resolve("test.cbz");
        try (ZipOutputStream zos = new ZipOutputStream(new FileOutputStream(cbzPath.toFile()))) {
            zos.putNextEntry(new ZipEntry("dummy.txt"));
            zos.write("content".getBytes());
            zos.closeEntry();
        }

        // Create output directory
        Path outputDir = tempDir.resolve("output");
        Files.createDirectory(outputDir);

        // Process file
        PipelineProcessor processor = new PipelineProcessor();
        processor.processFile(cbzPath.toFile(), outputDir.toFile());

        // Verify CBZ file remains intact
        File[] outputFiles = outputDir.toFile().listFiles();
        assertNotNull(outputFiles);
        assertEquals(1, outputFiles.length);
        assertEquals("test.cbz", outputFiles[0].getName());
        assertFalse(new File(outputDir.toFile(), "dummy.txt").exists(), "CBZ was unzipped");
    }
}

